    description: { de: "Ein verborgener Berg in der Region Ruma, der für seine steilen Hänge und die unberührte Flora bekannt ist.", hu: "Egy rejtett hegy a Ruma régióban, amely meredek lejtőiről és érintetlen növényvilágáról ismert.", ro: "Un munte ascuns în regiunea Ruma, faimos pentru pantele sale abrupte și flora virgină.", en: "A hidden mountain in the Ruma region, famous for its steep slopes and untouched flora." , es: "Una montaña escondida en la región de Ruma, conocida por sus laderas empinadas y su flora virgen.", pt: "Uma montanha escondida na região de Ruma, conhecida pelas suas encostas íngremes e flora intocada.", fr: "Une montagne cachée dans la région de Ruma, connue pour ses pentes raides et sa flore intacte."},
