      de: ["Dimadong gehört zur Mowdok-Kette, die Teil der Arakan-Yoma-Ausläufer ist.", "Die Höhe des Gipfels wird auf knapp 1.000 Meter über dem Meeresspiegel geschätzt.", "Der Berg liegt im abgelegenen Thanchi-Upazila des Distrikts Bandarban.", "Das umliegende Gebiet ist von tropischem Bergregenwald bedeckt.", "Die Region ist Heimat verschiedener indigener Stämme wie der Mru und Khumi.", "Dimadong ist einer der am wenigsten erforschten Gipfel im Südosten Bangladeschs."],
      hu: ["Dimadong a Mowdok-hegység tagja, amely az Arakan-Yoma nyúlványaihoz tartozik.", "A csúcs magasságát knapp 1000 méterre becsülik a tengerszint felett.", "A hegy Bandarban körzet távoli Thanchi Upazilájában található.", "A környező területet trópusi hegyi esőerdő borítja.", "A régió olyan őshonos törzsek otthona, mint a mru és a khumi.", "Dimadong Banglades délkeleti részének egyik legkevésbé felfedezett csúcsa."],
      ro: ["Dimadong aparține lanțului Mowdok, care face parte din ramificațiile Arakan Yoma.", "Înălțimea vârfului este estimată la aproape 1.000 de metri deasupra mării.", "Muntele se află în regiunea izolată Thanchi Upazila din districtul Bandarban.", "Zona înconjurătoare este acoperită de pădure tropicală montană de ploaie.", "Regiunea este locuită de diverse triburi indigene, precum Mru și Khumi.", "Dimadong este unul dintre cele mai puțin explorate vârfuri din sud-estul Bangladeshului."],
      en: ["Dimadong is a prominent summit in the Mowdok range of the Chittagong Hill Tracts.", "The peak stands at an elevation of approximately 1,000 meters (3,280 feet).", "It is located near the international boundary between Bangladesh and Myanmar.", "The mountain is surrounded by dense tropical evergreen forest cover.", "Indigenous communities in the area practice traditional Jhum (slash-and-burn) farming.", "Access to the peak usually requires specialized permits and local guides."],
